var TREE_BREAK_SPEED_STEP = 0.25;
var TREE_BREAK_SPEED_DEFAULT = 1;
var TREE_COUNT_MOTION_TIME_DEFAULT = false;
var TREE_LOG_BREAKAGE_DEFAULT = true;
var TREE_PLAYER_CARRYING_DEFAULT = true;
var TREE_SMOOTH_PLAYER_CARRYING_DEFAULT = true;
