// src/ui/Settings.ts
var TREE_SETTINGS_COMMAND = "treephysics:settings";
var installed = false;
function installTreeSettings() {
  if (installed) return;
  installed = true;
  system13.beforeEvents.startup.subscribe((event) => {
    event.customCommandRegistry.registerCommand({
      name: TREE_SETTINGS_COMMAND,
      description: "ui.treephysics.settings.command.description",
      permissionLevel: CommandPermissionLevel2.Any,
      cheatsRequired: false
    }, (origin) => {
      const source = origin.sourceEntity;
      if (source?.typeId !== "minecraft:player") {
        return { status: CustomCommandStatus.Failure };
      }
      queueTreeSettingsForm(source);
      return { status: CustomCommandStatus.Success };
    });
  });
}

// src/content/tree/felling/BreakTiming.ts
function scaleTreeBreakTicks(ticks) {
  const baseTicks = Number.isFinite(ticks) ? Math.max(1, Math.floor(ticks)) : 1;
  const speed = getTreeBreakSpeedMultiplier();
  return speed === 0 ? baseTicks : Math.max(1, Math.round(baseTicks / speed));
}
function getTreeBreakTiming(logCount, ticksPerLog) {
  const normalizedLogCount = Number.isFinite(logCount) ? Math.max(1, Math.floor(logCount)) : 1;
  if (getTreeBreakSpeedMultiplier() >= TREE_BREAK_SPEED_MAX) {
    return { sleepTicksPerLog: 1, sleepTimeoutTicks: 1 };
  }
  const scaledTicksPerLog = scaleTreeBreakTicks(ticksPerLog);
  return {
    sleepTicksPerLog: scaledTicksPerLog,
    sleepTimeoutTicks: normalizedLogCount * scaledTicksPerLog
  };
}

